import { useState, type FormEvent } from "react";
import { useNavigate, useSearchParams } from "react-router-dom";
import { isDomainError } from "../../shared/api/domain-error";
import { useCapabilities } from "../../shared/auth/use-capabilities";
import { RegionState } from "../../features/datasets/components/RegionState";
import { datasetRegionStateForError } from "../../features/datasets/components/error-state";
import {
  useCreateDatasetMutation,
  useDatasetFacetsQuery,
  useDatasetsPageCapabilitiesQuery,
  useDatasetSummaryQuery,
  useDatasetsQuery,
} from "../../features/datasets/api";
import { routes } from "../../features/datasets/routing";
import type { DatasetId } from "../../entities/dataset";
import datasetsQueryCodec, { type DatasetsSearch } from "./query-codec";
import "../../features/datasets/components/datasets.css";

function nextIdempotencyKey(): string {
  return globalThis.crypto?.randomUUID?.() ?? `dataset-create-${Date.now()}-${Math.random().toString(36).slice(2)}`;
}

export function DatasetsPage() {
  const navigate = useNavigate();
  const [params] = useSearchParams();
  const search = datasetsQueryCodec.parse(params);
  const capabilities = useCapabilities();
  const canRead = capabilities.has("dataset.read");
  const query = useDatasetsQuery(search, canRead);
  const summary = useDatasetSummaryQuery(search, canRead);
  const facets = useDatasetFacetsQuery(search, canRead);
  const pageCapabilities = useDatasetsPageCapabilitiesQuery(canRead);
  const createMutation = useCreateDatasetMutation();
  const [createOpen, setCreateOpen] = useState(false);
  const [createdDatasetId, setCreatedDatasetId] = useState<DatasetId | null>(null);
  const [name, setName] = useState("");
  const [description, setDescription] = useState("");
  const [labels, setLabels] = useState("");

  const change = (changes: Partial<DatasetsSearch>) => {
    const next = datasetsQueryCodec.withChanges(search, changes);
    navigate(routes.datasets.build(next), { replace: true });
  };

  const submitCreate = (event: FormEvent) => {
    event.preventDefault();
    createMutation.mutate({
      idempotencyKey: nextIdempotencyKey(),
      command: {
        name,
        description,
        labels: [...new Set(labels.split(",").map((value) => value.trim()).filter(Boolean))],
      },
    }, {
      onSuccess: (created) => {
        setCreateOpen(false);
        setCreatedDatasetId(created.dataset_id as DatasetId);
        const firstWindow = datasetsQueryCodec.withChanges(search, {
          after: undefined,
          before: undefined,
        });
        navigate(routes.datasets.build(firstWindow), { replace: true });
      },
    });
  };

  const items = query.data?.items ?? [];
  const canCreate = capabilities.has("dataset.create") &&
    pageCapabilities.data?.allowedActions.includes("CREATE_DATASET") === true;

  return (
    <main className="dataset-page" data-page-id="P05">
      <header className="dataset-page-header">
        <div><p className="dataset-eyebrow">Data assets</p><h1>数据集</h1><p>服务端筛选、稳定排序与游标分页；默认每页 20 条。</p></div>
        <div className="dataset-actions">
          <button type="button" className="dataset-button" disabled={!canCreate} onClick={() => setCreateOpen(true)}>创建数据集</button>
        </div>
      </header>

      <section className="dataset-filter-bar" aria-label="数据集筛选">
        <label>搜索<input value={search.q ?? ""} placeholder="名称、任务或机器人" onChange={(event) => change({ q: event.target.value || undefined })} /></label>
        <label>资产状态<select value={search.assetState ?? ""} onChange={(event) => change({ assetState: (event.target.value || undefined) as DatasetsSearch["assetState"] })}><option value="">全部</option>{(facets.data?.assetStates ?? [{ value: "ready", count: "0" }, { value: "validating", count: "0" }, { value: "problem", count: "0" }, { value: "frozen", count: "0" }]).map((item) => <option key={item.value} value={item.value}>{item.value} ({item.count})</option>)}</select></label>
        <label>存储层级<select value={search.storageClass ?? ""} onChange={(event) => change({ storageClass: (event.target.value || undefined) as DatasetsSearch["storageClass"] })}><option value="">全部</option>{(facets.data?.storageClasses ?? [{ value: "standard", count: "0" }, { value: "ia", count: "0" }, { value: "archive", count: "0" }]).map((item) => <option key={item.value} value={item.value}>{item.value} ({item.count})</option>)}</select></label>
        <label>排序<select value={search.sort} onChange={(event) => change({ sort: event.target.value as DatasetsSearch["sort"] })}><option value="activityDesc">最近活动</option><option value="createdDesc">最近创建</option><option value="nameAsc">名称</option></select></label>
        <button type="button" className="dataset-button dataset-button--secondary" onClick={() => navigate(routes.datasets.build({}))}>清除</button>
      </section>

      {summary.isError ? <RegionState state={datasetRegionStateForError(summary.error)} message="摘要区域加载失败；列表仍可独立使用。" onRetry={() => void summary.refetch()} /> : <dl className="dataset-metrics" aria-label="授权筛选摘要">
        {[['数据集', summary.data?.datasetCount ?? '—'], ['Episodes', summary.data?.episodeCount ?? '—'], ['待复核版本', summary.data?.pendingReviewVersionCount ?? '—'], ['已退回版本', summary.data?.returnedVersionCount ?? '—'], ['可处理草稿', summary.data?.actionableDraftCount ?? '—']].map(([label, value]) => <div className="dataset-metric" key={label}><dt>{label}</dt><dd>{value}</dd><small>服务端授权聚合</small></div>)}
      </dl>}

      {createdDatasetId ? <section className="dataset-band" role="status"><div className="dataset-band-heading"><div><h2>数据集已创建</h2><p><code>{createdDatasetId}</code> 是空 Dataset；没有隐式创建 Version。</p></div><button type="button" className="dataset-button" onClick={() => navigate(routes.datasetDetail.build({ datasetId: createdDatasetId }))}>查看数据集</button></div></section> : null}

      {capabilities.loading ? <RegionState state="first-loading" /> : capabilities.failed || !capabilities.has("dataset.read") ? <RegionState state="forbidden" /> : query.isPending ? <RegionState state="first-loading" /> : query.isError ? (
        <RegionState state={datasetRegionStateForError(query.error)} message={query.error instanceof Error ? query.error.message : undefined} requestId={isDomainError(query.error) ? query.error.requestId : null} onRetry={() => void query.refetch()} />
      ) : items.length === 0 ? <RegionState state={search.q || search.assetState || search.storageClass ? "filtered-empty" : "empty"} /> : (
        <section className="dataset-table-shell" aria-busy={query.isFetching}>
          {query.isFetching ? <RegionState state="refreshing" /> : null}
          <div className="dataset-table-scroll"><table className="dataset-table"><thead><tr><th>数据集</th><th>当前 Ready</th><th>Episodes</th><th>待复核</th><th>已退回</th><th>活动时间</th><th>操作</th></tr></thead><tbody>
            {items.map((item) => <tr key={item.datasetId}>
              <td><button className="dataset-link" type="button" onClick={() => navigate(routes.datasetDetail.build({ datasetId: item.datasetId }))}><strong>{item.name}</strong><small>{item.datasetId}</small></button></td>
              <td>{item.currentVersion ? <><strong>{item.currentVersion.displayVersion}</strong><small>{item.currentVersion.versionId}</small></> : <span className="dataset-status dataset-status--unknown">尚未导入</span>}</td>
              <td>{item.episodeCount}</td><td>{item.pendingReviewVersionCount}</td><td>{item.returnedVersionCount}</td><td>{new Date(item.datasetActivityAt).toLocaleString()}</td>
              <td><div className="dataset-actions"><button type="button" className="dataset-link" onClick={() => navigate(routes.datasetDetail.build({ datasetId: item.datasetId }))}>打开</button></div></td>
            </tr>)}
          </tbody></table></div>
          <footer className="dataset-table-footer"><span>快照 {query.data.snapshotAt}</span><nav className="dataset-pagination" aria-label="游标分页"><button className="dataset-button dataset-button--secondary" type="button" disabled={!query.data.pageInfo.hasPreviousPage} onClick={() => change({ before: query.data!.pageInfo.before ?? undefined })}>上一页</button><button className="dataset-button dataset-button--secondary" type="button" disabled={!query.data.pageInfo.hasNextPage} onClick={() => change({ after: query.data!.pageInfo.after ?? undefined })}>下一页</button></nav></footer>
        </section>
      )}

      {createOpen ? <div className="dataset-dialog-backdrop"><form className="dataset-dialog" role="dialog" aria-modal="true" aria-labelledby="create-dataset-title" onSubmit={submitCreate}><p className="dataset-eyebrow">Empty dataset</p><h2 id="create-dataset-title">创建数据集</h2><p>只创建空 Dataset，不隐式创建 Version。</p><label>名称<input required maxLength={256} value={name} onChange={(event) => setName(event.target.value)} /></label><label>描述<textarea maxLength={4096} value={description} onChange={(event) => setDescription(event.target.value)} /></label><label>标签（逗号分隔）<input value={labels} onChange={(event) => setLabels(event.target.value)} /></label>{createMutation.isError ? <p role="alert">{createMutation.error instanceof Error ? createMutation.error.message : "创建失败"}</p> : null}<footer><button type="button" className="dataset-button dataset-button--secondary" onClick={() => setCreateOpen(false)}>取消</button><button className="dataset-button" disabled={createMutation.isPending || !name.trim()}>{createMutation.isPending ? "提交中…" : "创建"}</button></footer></form></div> : null}
    </main>
  );
}

export default DatasetsPage;
